var VW = { i:0, list:[] }, VZ = { s:1, x:0, y:0, quiet:0 };
function vwOpenList(list, i){ var vw = document.getElementById('vw'); VW.list = list; VW.i = i; vwShow(); vw.hidden = false; requestAnimationFrame(function(){ vw.classList.add('on'); }); document.documentElement.classList.add('noscroll'); }
function vzApply(anim){ var im = document.querySelector('#vw .vw-st img'); if (!im) return; im.style.transition = anim ? 'transform .25s ease' : 'none'; im.style.transform = 'translate('+VZ.x+'px,'+VZ.y+'px) scale('+VZ.s+')'; document.getElementById('vw').classList.toggle('zoomed', VZ.s > 1.01); }
function vzClamp(){ var im = document.querySelector('#vw .vw-st img'); if (!im) return; var mx = im.offsetWidth*(VZ.s-1)/2, my = im.offsetHeight*(VZ.s-1)/2; VZ.x = Math.max(-mx, Math.min(mx, VZ.x)); VZ.y = Math.max(-my, Math.min(my, VZ.y)); }
function vzReset(anim){ VZ.s = 1; VZ.x = 0; VZ.y = 0; vzApply(anim); }
function vwShow(){
  var m = VW.list[VW.i], st = document.querySelector('#vw .vw-st');
  st.innerHTML = m.type==='video' ? '<video src="'+m.src+'" controls playsinline autoplay'+(m.poster?' poster="'+m.poster+'"':'')+'></video>' : '<img src="'+m.src+'" alt="" draggable="false">';
  document.querySelector('#vw .vw-cap').textContent = VW.list.length>1 ? (VW.i+1)+' / '+VW.list.length : '';
  document.getElementById('vw').classList.toggle('single', VW.list.length < 2); vzReset(false);
  var nx = VW.list[VW.i+1]; if (nx && nx.type==='img'){ var pre = new Image(); pre.src = nx.src; }
}
function saveFile(src, fn, b){
  if (b) b.classList.add('busy');
  fetch(src).then(function(r){ return r.blob(); }).then(function(blob){
    if (b) b.classList.remove('busy');
    try { var f = new File([blob], fn, { type:blob.type || 'image/jpeg' }); if (navigator.canShare && navigator.canShare({ files:[f] })){ navigator.share({ files:[f] }).catch(function(){}); return; } } catch(_){}
    var a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = fn; document.body.appendChild(a); a.click(); setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 2000);
  }).catch(function(){ if (b) b.classList.remove('busy'); window.open(src, '_blank'); });
}
function vwDownload(){ var m = VW.list[VW.i]; saveFile(m.src, 'صحبة-أجيال-'+(VW.i+1)+'.'+(m.type==='video'?'mp4':'jpg'), document.querySelector('#vw .vw-dl')); }
function vwClose(){ var vw = document.getElementById('vw'); vw.classList.remove('on','zoomed'); document.documentElement.classList.remove('noscroll'); var v = vw.querySelector('video'); if (v) v.pause(); setTimeout(function(){ vw.hidden = true; vw.querySelector('.vw-st').innerHTML = ''; }, 250); }
function vwStep(d){ if (VW.list.length < 2 || VZ.s > 1.01) return; var v = document.querySelector('#vw video'); if (v) v.pause(); VW.i = (VW.i + d + VW.list.length) % VW.list.length; vwShow(); }
(function(){
  var vw = document.getElementById('vw'), st = vw.querySelector('.vw-st'), g = null, lastTap = 0;
  function dist(t){ return Math.hypot(t[0].clientX-t[1].clientX, t[0].clientY-t[1].clientY); }
  function mid(t){ return { x:(t[0].clientX+t[1].clientX)/2, y:(t[0].clientY+t[1].clientY)/2 }; }
  function isImg(){ return !!st.querySelector('img'); }
  st.addEventListener('touchstart', function(ev){ var t = ev.touches;
    if (!g) g = { multi:false, moved:false, x0:t[0].clientX, y0:t[0].clientY, t0:Date.now(), sx:VZ.x, sy:VZ.y };
    if (t.length >= 2 && isImg()){ g.multi = true; var m = mid(t); g.d0 = dist(t); g.s0 = VZ.s; g.mx = m.x; g.my = m.y; g.px = VZ.x; g.py = VZ.y; }
    else if (t.length === 1){ g.x0 = t[0].clientX; g.y0 = t[0].clientY; g.sx = VZ.x; g.sy = VZ.y; }
  }, { passive:true });
  st.addEventListener('touchmove', function(ev){ if (!g) return; var t = ev.touches;
    if (t.length >= 2 && isImg() && g.d0){ ev.preventDefault(); var m = mid(t); VZ.s = Math.max(1, Math.min(4, g.s0 * dist(t) / g.d0)); VZ.x = g.px + (m.x - g.mx); VZ.y = g.py + (m.y - g.my); vzClamp(); vzApply(false); g.moved = true; }
    else if (t.length === 1){ var dx = t[0].clientX - g.x0, dy = t[0].clientY - g.y0; if (Math.abs(dx) > 6 || Math.abs(dy) > 6) g.moved = true; if (VZ.s > 1.01){ ev.preventDefault(); VZ.x = g.sx + dx; VZ.y = g.sy + dy; vzClamp(); vzApply(false); } }
  }, { passive:false });
  st.addEventListener('touchend', function(ev){ if (!g) return;
    if (ev.touches.length > 0){ if (ev.touches.length === 1){ g.x0 = ev.touches[0].clientX; g.y0 = ev.touches[0].clientY; g.sx = VZ.x; g.sy = VZ.y; g.d0 = 0; } return; }
    var c = ev.changedTouches[0], dx = c.clientX - g.x0, dy = c.clientY - g.y0, now = Date.now();
    if (g.multi || g.moved) VZ.quiet = now + 450;
    if (g.multi){ if (VZ.s < 1.05) vzReset(true); }
    else if (VZ.s <= 1.01 && Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy)*1.5 && now - g.t0 < 800){ vwStep(dx > 0 ? -1 : 1); }
    else if (!g.moved && isImg()){
      if (now - lastTap < 300){ VZ.quiet = now + 450; if (VZ.s > 1.01) vzReset(true); else { var r = st.getBoundingClientRect(); VZ.s = 2.5; VZ.x = (r.left + r.width/2 - c.clientX) * 1.5; VZ.y = (r.top + r.height/2 - c.clientY) * 1.5; vzClamp(); vzApply(true); } lastTap = 0; }
      else lastTap = now;
    }
    g = null;
  }, { passive:true });
  st.addEventListener('dblclick', function(){ if (!isImg()) return; VZ.quiet = Date.now() + 300; if (VZ.s > 1.01) vzReset(true); else { VZ.s = 2.5; vzApply(true); } });
})();

