/* ملاحظة الشاشة الرئيسية */
#inst{position:fixed;z-index:90;left:12px;right:12px;bottom:calc(12px + var(--safeB));max-width:480px;margin-inline:auto;border-radius:24px;padding:14px;background:var(--solid);border:1px solid rgba(247,147,30,.45);box-shadow:0 18px 50px rgba(0,0,0,.35);transform:translateY(130%);opacity:0;transition:transform .55s var(--ease),opacity .4s}
#inst.show{transform:none;opacity:1}
#inst .hd{display:flex;align-items:center;gap:12px;padding-inline-end:34px}
#inst .app{flex:none;width:50px;height:50px;border-radius:13px;overflow:hidden}
#inst .app img{width:100%;height:100%}
#inst .tt{font-family:var(--disp);font-weight:800;font-size:16px;line-height:1.4}
#inst .why{font-size:13.5px;color:var(--t2);line-height:1.5;text-wrap:balance}
#inst .x{position:absolute;top:10px;inset-inline-end:10px;width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--chip);border:1px solid var(--line2)}
#inst .x svg{width:14px;height:14px}
#inst ol{list-style:none;margin-top:12px;display:grid;gap:6px;counter-reset:s}
#inst li{counter-increment:s;display:flex;align-items:center;gap:10px;font-size:14px;line-height:1.55;color:var(--t2)}
#inst li::before{content:counter(s);flex:none;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-family:var(--disp);font-weight:700;font-size:12px;color:#fff;background:linear-gradient(135deg,var(--am),var(--or))}
#inst li b{color:var(--ink)}
#inst .ico{display:inline-grid;place-items:center;width:22px;height:22px;border-radius:6px;background:var(--chip);vertical-align:middle;margin-inline:2px;color:var(--sky)}
#inst .ico svg{width:14px;height:14px}


/* ================= الهوية: زخرفة إسلامية + ألوان الشعار ================= */
:root{ --gO:linear-gradient(135deg,#fbb03b,#f58634); --gB:linear-gradient(135deg,#27aae1,#2b3990); --arc:linear-gradient(90deg,#f7931e,#c46b6b 45%,#5a4a9a 70%,#1c75bc 88%,#00aeef); --star:polygon(50% 0%,65.3% 13%,85.4% 14.6%,87% 34.7%,100% 50%,87% 65.3%,85.4% 85.4%,65.3% 87%,50% 100%,34.7% 87%,14.6% 85.4%,13% 65.3%,0% 50%,13% 34.7%,14.6% 14.6%,34.7% 13%); }
:root[data-theme="dark"]{ --pat:rgba(247,147,30,.10); --pat2:rgba(255,255,255,.05) }
:root[data-theme="light"]{ --pat:rgba(245,134,52,.13); --pat2:rgba(43,57,144,.06) }
.pat{position:absolute;inset:0;z-index:0;pointer-events:none;background:var(--pat);-webkit-mask:url(assets/pattern.svg) 0 0/72px 72px repeat;mask:url(assets/pattern.svg) 0 0/72px 72px repeat}
.pat.fade{-webkit-mask:url(assets/pattern.svg) 0 0/72px 72px repeat,linear-gradient(#000,transparent 85%);-webkit-mask-composite:source-in;mask:url(assets/pattern.svg) 0 0/72px 72px repeat intersect,linear-gradient(#000,transparent 85%)}
.pat.b2{background:var(--pat2)}
.band>.wrap{position:relative;z-index:1}
.star{display:inline-grid;place-items:center;clip-path:var(--star);background:var(--gO);color:#fff}
.star.b{background:var(--gB)}
.arcline{display:block;height:3px;border-radius:3px;background:var(--arc)}
/* hero */
.hero{background:#060d20}
.hero .pat{top:auto;height:62%;background:rgba(247,147,30,.13)}
.hero .slash{display:none}
.hero .arcb{position:absolute;left:0;right:0;height:4px;background:var(--arc);box-shadow:0 0 22px rgba(247,147,30,.45);transform:translateY(-2px)}
.hero .in{display:block;padding-top:0}
.hero .head{display:flex;align-items:center;gap:14px;margin-top:-44px;position:relative}
.medal{flex:none;width:112px;height:112px;position:relative;filter:drop-shadow(0 14px 28px rgba(0,0,0,.45))}
.medal::before{content:"";position:absolute;inset:0;clip-path:var(--star);background:var(--gO)}
.medal::after{content:"";position:absolute;inset:6px;clip-path:var(--star);background:#fff}
.medal img{position:absolute;inset:22%;width:56%;height:56%;object-fit:contain;z-index:1}
.hero .head .tt{padding-top:40px}
.hero .lg{display:none}
.h-title{margin-top:0;font-size:clamp(40px,11.5vw,104px);line-height:1.35;white-space:nowrap}
.h-title .g{background:var(--gO);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero .k{display:block;font-family:var(--disp);font-weight:600;font-size:14px;color:rgba(255,255,255,.72);margin-top:-4px}
.hero .tags span svg{color:#fbb03b}
.btn-p{background:var(--gO)}
@media (min-width:900px){ .hero .in{margin-top:0} .medal{width:150px;height:150px} .hero .head{margin-top:-60px;gap:22px} .hero .head .tt{padding-top:56px} }
/* section headers */
.sh .eyebrow{gap:10px}
.sh .eyebrow b{display:none}
.sh .eyebrow .star{width:26px;height:26px}
.sh .eyebrow .star::after{content:"";width:8px;height:8px;border-radius:50%;background:#fff}
.sh .eyebrow::after{display:none}
.sh h2{margin-top:0}
.sh .arcline{width:120px;margin-top:6px}
.sh{position:relative}
/* albums */
.alb.soon{border:1px solid var(--line2)}
.alb.soon::after{content:"";position:absolute;left:0;right:0;top:0;height:3px;background:var(--arc);opacity:.85}
.alb.soon .ai{border-radius:0;clip-path:var(--star);width:56px;height:56px;box-shadow:none}
.alb.soon.c1 .ai,.alb.soon.c3 .ai{background:var(--gO)}
.alb.soon.c2 .ai{background:var(--gB)}
.alb.soon .ai svg{width:23px;height:23px}
.alb.soon.c1,.alb.soon.c2,.alb.soon.c3{background:var(--card)}
.alb .bgp{position:absolute;inset:0;z-index:-1;background:var(--pat);-webkit-mask:url(assets/pattern.svg) 0 0/56px 56px repeat,linear-gradient(200deg,#000,transparent 60%);-webkit-mask-composite:source-in;mask:url(assets/pattern.svg) 0 0/56px 56px repeat intersect,linear-gradient(200deg,#000,transparent 60%)}
/* pillars */
.pl .ic{border-radius:0;clip-path:var(--star);box-shadow:none;width:58px;height:58px}
.pl.c1 .ic,.pl.c3 .ic{background:var(--gO)} .pl.c2 .ic{background:var(--gB)}
.pl{border-top:3px solid transparent;background:linear-gradient(var(--card),var(--card)) padding-box,var(--arc) border-box;border-width:3px 1px 1px;border-color:transparent}
:root[data-theme="dark"] .pl{background:linear-gradient(#0e1a3b,#0e1a3b) padding-box,var(--arc) border-box}
/* mission */
.mission>*:not(.pat):not(.mark){position:relative}
.mission{background:linear-gradient(135deg,#0b1a44,#14286a 60%,#0a1736)}
.mission .pat{background:rgba(251,176,59,.16)}
.mission h2 em{background:var(--gO);-webkit-background-clip:text;background-clip:text;color:transparent}
/* feat + stats */
.st2 b{background:var(--gO);-webkit-background-clip:text;background-clip:text;color:transparent}
.st2 div{position:relative;overflow:hidden}
.st2 div::before{content:"";position:absolute;inset:0 0 auto 0;height:3px;background:var(--arc)}
/* footer */
footer .pat{background:var(--pat)}
footer .wrap{position:relative;z-index:1}
footer::before{background:var(--arc);height:3px;width:100%;left:0;transform:none}
.f-logos .a{box-shadow:none;border-radius:0;clip-path:var(--star);background:var(--gO);padding:5px;width:84px;height:84px;position:relative}
.f-logos .a::after{content:"";position:absolute;inset:5px;clip-path:var(--star);background:#fff;z-index:0}
.f-logos .a img{position:relative;z-index:1;padding:14px}
/* header brand */
.brand .lg{border-radius:0;clip-path:var(--star);box-shadow:none;background:var(--gO);padding:3px;position:relative;width:46px;height:46px}
.brand .lg::after{content:"";position:absolute;inset:3px;clip-path:var(--star);background:#fff}
.brand .lg img{position:relative;z-index:1;padding:7px}
/* splash */
#splash .d{border-radius:0;clip-path:var(--star);box-shadow:none;background:var(--gO);padding:6px;width:140px;height:140px;position:relative}
#splash .d::after{content:"";position:absolute;inset:6px;clip-path:var(--star);background:#fff}
#splash .d img{position:relative;z-index:1;padding:20px}
#splash .pat{background:rgba(247,147,30,.12)}

